const nl = "تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.";
const ll = "حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.";
const rl = "حضور دروس المعلمين وفق جدول يعتمده مدير المدرسة ويقوم بالتدريس لعدد حصص مادة التخصص وبما لا يتجاوز 8 حصص.";
const Qu = "تفعيل مجالس ولجان المدرسة وفرق العمل والإشراف عليها وممارسة الصلاحيات المعتمدة ومتابعة تنفيذها.";
const Ku = "الإشراف على تهيئة وتنظيم وتجهيز مرافق المدرسة قبل وأثناء الدراسة في المواعيد المحددة.";
const Yu = ["شهادة جامعية.", "عضوية في اللجان ذات العلاقة بالوظيفة، أو ترأسه لفرق عمل ذات علاقة.", "إجمالي خبرة تعليمية لا تقل عن 4 سنوات."];

export const SCHOOL_JOBS: any[] = [{id:"manager",title:"مدير المدرسة",page:29,link:["يرتبط مدير المدرسة (الابتدائية / المتوسطة / الثانوية) حسب مرحلتها، بـ (مدير المرحلة) المعني في قسم المدارس بإدارة التعليم العامة.","ترتبط مديرة رياض الأطفال بمدير قسم رياض الأطفال في إدارة التعليم العامة.","ترتبط مديرة الحضانة بمدير قسم الحضانة في إدارة التعليم العامة.","يرتبط مدير مدرسة التعليم المستمر بمدير قسم التعليم المستمر في إدارة التعليم العامة.","يرتبط مدير مدرسة الطلاب ذوي الإعاقة (باستثناء مدارس الدمج) بمدير قسم ذوي الإعاقة بإدارة التعليم العامة (باستثناء المراكز أو المعاهد أو ما في حكمها المختصة بذوي الإعاقة والتي صدر بها تنظيم مستقل معتمد من صاحب الصلاحية).","يرتبط مدير مدرسة الموهوبين بمدير قسم الموهوبين بإدارة التعليم العامة."],goal:"الإشراف على المدرسة ومتابعة مستوى الأداء والتخطيط والتنظيم والتقويم لرعاية شؤون الطلاب في المدرسة ومعالجة جميع القضايا المتعلقة بهم تربويًا وتعليميًا لتحقيق الأهداف وتحسين نواتج التعلم.",qualifications:["شهادة جامعية أو أعلى.","الرخصة المهنية المطلوبة رتبة معلم ممارس فأعلى.","عضوية في اللجان ذات العلاقة بالوظيفة، أو ترأسه لفرق عمل ذات علاقة.","خبرة 7 سنوات، منها 4 سنوات في التدريس.","خبرة 3 سنوات كوكيل مدرسة (باستثناء مديري المدارس الصغيرة)."],tasks:[nl,"قيادة عملية إعداد خطة المدرسة ومتابعة تنفيذها بعد اعتمادها، بما يحقق الاستفادة المثلى من الخبرات والمواهب والموارد في المدرسة.","الحفاظ على كفاءة وفعالية الأداء داخل المدرسة، واستثمار الوقت والموارد لتحسين نواتج التعلم وجودة الخدمة المقدمة، وتحقيق السلامة المدرسية.","الإشراف على تنفيذ برامج الوعي الفكري وخططه وقواعده المعتمدة، وتعزيز الوسطية والاعتدال الفكري والتأكد من سلامة البيئة التعليمية من الفكر المتطرف والظواهر السلبية.","حماية مجتمع المدرسة من كل ما يؤدي إلى ضعف الالتزام الوطني بما لا يتماشى مع الوسطية والاعتدال الفكري.","متابعة حالات المخالفات أو الاشتباه في المخالفات للسياسات العامة، والالتزام الفكري والوطني.","رصد حالات المخالفات الفكرية، أو الاشتباه في وجود مخالفات للسياسات العامة، والالتزام الفكري والوطني بما ينافي الوسطية والاعتدال الفكري في المدارس، ومعالجتها بناءً على القواعد والإجراءات المعتمدة.","الرفع الفوري لمدير عام التعليم / صاحب الصلاحية في حالات المخالفات الفكرية أو المخالفات للسياسات العامة التي لم تتم معالجتها.","تزويد إدارة التعليم العامة بتقارير دورية عن حالة الوعي الفكري، وفقًا للقواعد والإجراءات المعتمدة.","تحديد الاحتياج من الكوادر المهنية والمفاضلة بينهم بوضع الأهداف الفردية ومؤشرات الأداء الرئيسية لكل من منسوبي المدرسة، ومناقشتها معهم.","توزيع المهام والواجبات على منسوبي المدرسة وإصدار التكاليف اللازمة لإنجاز أعمالهم ومناقشتها لتوضيح مضامينها والعمل بموجبها.","مراجعة وتقويم أداء منسوبي المدرسة بشكل دوري، ومناقشتهم وتقديم تغذية راجعة لهم، واعتماد التقويم النهائي لأدائهم، والتأكد من أنها تتماشى مع اللوائح والتعليمات.","توفير التوجيه المناسب لتحسين أداء منسوبي المدرسة، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لإدارة التعليم العامة.","تمكين الموظفين وإشراكهم في إعداد الخطة التشغيلية وتحسين العمليات داخل المدرسة بما يعزز لديهم شعور الانتماء للمدرسة.","التأكد من وجود نظام مناسب لإدارة المدرسة ولمراجعة وتحسين العمليات الرئيسية (نمط إدارة للعمل يتناسب مع وضع المدرسة).","العمل مع وكلاء المدرسة لرسم الخطط التطويرية لأداء الموظفين.","تشجيع منسوبي المدرسة على الاستفادة من الخبرات المكتسبة والتطوير في تحسين الأداء المدرسي.","الإشراف على تهيئة بيئة تعليمية محفزة داخل المدرسة، ورفع الروح المعنوية بين المعلمين والطلاب وأولياء الأمور.","مراجعة أداء مبادرات المدرسة وأهدافها وإجراء حوارات حول الأداء مع منسوبي المدرسة مبني على تقارير الأداء للتأكد من تلبيتها لأهداف الأداء.","متابعة التحصيل الدراسي وتقدم الطلاب داخل المدرسة، والتأكد من مدى فعالية أساليب التدريس واتخاذ الإجراءات المناسبة حيالها.","الإشراف على عمليات التدريس واستخدام استراتيجيات التعلم داخل الفصول وفق الجدول الزمني المخصص لها وبما يضمن تحقيق أهداف المقررات الدراسية.","توفير بيئة تعليمية آمنة وجاذبة، وذلك بتوفير الدعم المستمر للاحترام والانضباط ورفع الروح المعنوية بين المعلمين والطلاب وأولياء الأمور.","إدارة عمليات الانضباط داخل المدرسة ومتابعة حضور المعلمين والقيام بالترتيبات الملائمة لمعالجة العجز الطارئ من داخل المدرسة وفق التعليمات المعتمدة.","متابعة أداء أعمال الهيئة التعليمية والإدارية للمدرسة وذلك من خلال الزيارات الدورية لهم والاطلاع على أعمالهم وأنشطتهم ومشاركاتهم.","الإشراف على مجالس أولياء الأمور وتفعيل دورها في المدرسة، واعتماد التوصيات الصادرة عن لجان المدرسة، وفق اللوائح والتعليمات المنظمة.","متابعة التزام المدرسة بالسياسات والإجراءات التي تم وضعها مركزيًا من قبل الوزارة، ومتابعة اللوائح والأنظمة والتعاميم الهامة الصادرة من جهات الاختصاص وإطلاع جميع منسوبي المدرسة عليها ومناقشتها لتوضيح مضامينها والعمل بموجبها.","تفعيل التعليم الإلكتروني بقنواته المختلفة وتشجيعه، وتطبيق الممارسات الإدارية والتعليمية وفق التعاميم المنظمة، لضمان جودة العملية التعليمية، ومتابعة التطبيقات في منصات التعليم الإلكتروني المعتمدة، وتعزيز الاستخدام الأمثل لمصادر التعلم والمعدات والتقنية لدعم أنظمة المدرسة.","إدارة ميزانية المدرسة على النحو الأمثل لتحقيق أهداف المدرسة.","تحليل واستخدام المعلومات والبيانات لدعم العمليات المدرسية وخطط العمل.","الالتزام بالسياسات والضوابط والمعايير المعتمدة والمنظمة للنشاط الإعلامي للمدرسة وحوكمة استخدام حسابات شبكات التواصل الاجتماعي للمدرسة التابعة لوزارة التعليم.",ll,rl,Qu,Ku,"التواصل الفعال والتنسيق والتعاون مع مقدمي خدمات دعم التميز المدرسي وغيرهم ممن تقتضي طبيعة عملهم زيارة المدرسة للحصول على أفضل خدمة ممكنة.","إعداد تقييم أداء مرؤوسيه المباشرين ومناقشة الأهداف معهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطائهم تغذية راجعة بناءً عليها، ورفعها لمدير القسم الذي يرتبط به للاعتماد وفق الحوكمة المعتمدة لذلك.","القيام بأية مهام يكلف بها من هو المسؤول المباشر وتتناسب مع مهامه / مؤهلاته."]},{id:"deputy-edu",title:"وكيل المدرسة للشؤون التعليمية",page:31,link:["يرتبط بمدير المدرسة."],goal:"الإشراف على عمليات التعليم والتعلم، ومتابعة مستوى الأداء التعليمي ومراجعة التحصيل الدراسي للطلاب وتحليله بشكل دوري لتحسين مستوى أدائهم، ومتابعة أداء المعلمين وتطويرهم مهنيًا.",qualifications:Yu,tasks:[nl,"التأكد من مطابقة أهداف المدرسة مع أهداف العملية التعليمية وشرح هذه الأهداف لجميع المعلمين.","إعداد تقييم أداء المعلمين ومناقشة الأهداف التعليمية للمواد الدراسية لكل معلم وتحديد مؤشرات الأداء الرئيسية له وإعطاء تغذية راجعة بناءً عليها بالتنسيق مع المعلم الخبير (إن وجد) للمادة وتقديم الدعم والتدريب لتحسين الأداء متى ما تطلب الأمر.","تحليل مستوى التحصيل لدى الطلاب ومتابعة أدائهم ومدى تطور مستوى تحصيلهم الدراسي، ومتابعة نتائجهم بشكل دوري، وعرض الحالات التي تتطلب إضافة حصص علاجية أو إثرائية على لجنة التوجيه الطلابي.","توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لمدير المدرسة.","إعداد الجداول المدرسية وتوزيع الأنصبة وفق التخصصات.","المشاركة في تصنيف المعلمين والاستفادة من خبراتهم المهنية والتعليمية.","المشاركة في قيادة وإدارة تنفيذ البرامج والأنشطة التعليمية والتربوية في المدرسة.","مراجعة ممارسات العملية التعليمية ورصد الصعوبات ومتابعة الظواهر المتعلقة بالشؤون التعليمية التي تظهر في المدرسة، والعناية بها ومتابعة معالجتها، وتحليل البيئة الداخلية والخارجية من أجل تطوير خطط العمل المتعلقة بالشؤون التعليمية في المدرسة حتى تلبي احتياجاتها الحالية والمستقبلية.","الإشراف على رصد التقدم في إنجاز الأعمال المكلف بها المعلمون وتحليل النتائج.","تقديم الدعم والمساندة والخبرة والمعرفة والرفع لمدير المدرسة ببرامج تدريب المعلمين لمساعدتهم على تحسين مستوى أدائهم.","التطوير المهني المستمر لاكتساب خبرة، ومهارات إدارية وقيادية.","متابعة وتحفيز المعلمين لاستخدام أدوات التقييم المتنوعة والاستفادة من المعلومات في تحسين مستوى الطلاب وتفعيل التعليم الإلكتروني بقنواته المختلفة وتشجيعه، وتطبيق الممارسات الإدارية والتعليمية بما يتناسب معه وفق التعاميم والضوابط المنظمة لذلك، لضمان جودة العملية التعليمية، وتعزيز الاستخدام الأمثل لمصادر التعلم والمعدات والتقنية لدعم أنظمة المدرسة.","تقديم الاقتراح الأمثل لجميع متطلبات التدريس (أجهزة العرض، النظام السمعي/المرئي-الفيديو ...) والاحتياجات الأساسية ذات الصلة (مواد مختبرية، معدات، ... إلخ) وذلك لحماية جميع الممتلكات داخل المدرسة والتأكد من استخدامها بأفضل طريقة تحقق نتائج التعلم المستهدفة.","متابعة تقييم أداء الطلاب وتطور مستوى تحصيلهم الدراسي، والإشراف الكامل على الإجراءات المتعلقة بذلك منذ بدايتها وحتى انتهائها.","تخطيط وإدارة الموارد المادية والتعليمية المخصصة للبرامج التعليمية.","تسهيل التواصل مع المعلمين من خلال قنوات تواصل تتسم بالشفافية.","متابعة مستوى تقدم الطلاب وأدائهم مع معلمي الصف فيما يتعلق بالأهداف المحددة لكل مادة دراسية، والتأكد من الالتزام بها واتخاذ إجراءات المتابعة والإجراءات المناسبة عند الضرورة.","إعداد التوقيت الزمني لفترات البرنامج اليومي (خاص برياض الأطفال).","إعداد جدول الإشراف والمناوبة اليومية ومتابعة تنفيذه بعد اعتماده من مدير المدرسة.",rl,Qu,Ku,"التنسيق والتعاون مع مقدمي خدمات دعم التميز المدرسي وغيرهم ممن تقتضي طبيعة عملهم زيارة المدرسة.",ll,"القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته."]},{id:"deputy-students",title:"وكيل المدرسة لشؤون الطلاب",page:33,link:["يرتبط بمدير المدرسة."],goal:"المشاركة في إدارة الشؤون الطلابية في المدرسة من حيث الإدارة، والتسجيل، والأنشطة الطلابية بما يتوافق مع أهداف المدرسة وبما يحسن من نواتج التعلم.",qualifications:["شهادة جامعية (علم نفس / علم اجتماع أو بكالوريوس تربوي + دبلوم توجيه وإرشاد).","عضوية في اللجان ذات العلاقة بالوظيفة، أو ترأسه لفرق عمل ذات علاقة.","إجمالي خبرة 8 سنوات.","خبرة 3 سنوات في التوجيه الطلابي أو النشاط الطلابي.","رتبة معلم ممارس بخبرة 4 سنوات فأعلى أو رتبة معلم متقدم أو معلم خبير."],tasks:[nl,"الإشراف على البرامج المتعلقة بالطلاب وتقديم الخدمات المناسبة لهم.","إعداد تقييم أداء الموظفين الذين يشرف عليهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطاء تغذية راجعة بناءً عليها.","توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لمدير المدرسة.","المساهمة في إنشاء قنوات تواصل تتسم بالشفافية مع أولياء أمور الطلاب.","الإشراف الكامل على الإجراءات المتعلقة بالقبول والتسجيل للطلاب منذ بدايتها وحتى انتهائها، والتأكد من أن تنفيذها يتم بطريقة فعالة، وتتبع فيها الضوابط والمعايير المعتمدة لها وفق الأنظمة واللوائح المنظمة لذلك لمختلف الفئات الطلابية المستهدفة.","متابعة تطبيق الخطط الدراسية لجميع الطلاب وفق حالاتهم وتخصصاتهم، بما في ذلك متابعة تنفيذ حصص النشاط عبر منصات التعليم الإلكتروني والتعليم عن بعد المعتمدة في الوزارة.","التأكد من تنظيم الأنشطة الطلابية بما يتماشى مع محتوى البرنامج المقدم وبما يتماشى مع أفضل الممارسات التطبيقية لها، والإشراف على تطبيقها.","تزويد الطلاب بالمعلومات والإشراف على تطوير برامج التوجيه لتهيئة الطلاب وتوجيههم فيما يتعلق باختيار (الجامعة / سوق العمل) بالتعاون مع معلميهم / والهيئة التعليمية وأولياء الأمور.","الإشراف الكامل على الإجراءات المتعلقة بالتوجيه الطلابي وفاعليته في القيام بدراسات الحالة للطلاب وتقديم الخدمات لهم، وإدارة الحالات المعقدة والحرجة منها إذا طلب الأمر ذلك.","إعداد الشراكات مع القطاعين الحكومي والخاص لدعم أو رعاية برامج المدرسة بما يدعم الأهداف التربوية، وفق الأنظمة واللوائح والتعليمات المنظمة لذلك، والعرض على لجنة التوجيه الطلابي.",rl,"المشاركة في إجراء تحليل البيانات والاستفادة من نتائج التعليم للطلاب في البرامج المقدمة لهم.","متابعة عمليات حضور وغياب الطلاب في المدرسة، ومتابعة سلوكهم والتأكد من تطبيق الأنظمة واللوائح المنظمة لذلك، والتواصل مع أولياء أمورهم فيما يتعلق بهذا الخصوص.","اعتماد توزيع المعلمين على برامج النشاط غير الصفي بالتنسيق مع رائد النشاط ومتابعة تنفيذ خطط وبرامج أنشطة الطلاب غير الصفية.","الإشراف على رصد الدرجات/المهارات على النظام الحاسوبي المعتمد ومتابعة إصدارها وتوزيعها على الطلاب.","إعداد مجالس أولياء الأمور ومتابعة تفعيلها في المدرسة، بالتنسيق مع الموجه الطلابي ورائد النشاط.","الإشراف على جميع العمليات المتعلقة بالسجلات والملفات الخاصة بالطلاب ومتابعة تحديثها وتنظيمها وحفظها واكتمالها في برنامج نور أو غيره من البرامج التي تعتمدها الوزارة.",ll,"القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته."]},{id:"deputy-school",title:"وكيل المدرسة للشؤون المدرسية",page:34,link:["يرتبط بمدير المدرسة."],goal:"الإشراف على الشؤون المتعلقة بالمدرسة لتوفير بيئة تعليمية مناسبة وآمنة، بما يحقق أهداف المدرسة وبما يحسن من نواتج التعلم.",qualifications:Yu,tasks:[nl,"إعداد تقييم أداء الموظفين الذين يشرف عليهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطاء تغذية راجعة بناءً عليها مع تقديم الدعم والتدريب لتحسين الأداء متى ما تطلب الأمر.","توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد احتياجات التطوير المهني اللازمة لهم ورفعها لمدير المدرسة.","المشاركة في إنشاء قنوات تواصل تتسم بالشفافية بين منسوبي المدرسة.","الإشراف على تنفيذ الخدمات الإدارية والمساندة للعملية التربوية والتعليمية وتأمين الاحتياجات ذات العلاقة بالمدرسة (تنظيم ملفات وسجلات منسوبي المدرسة، وتأمين الاحتياجات من الوثائق الوظيفية، وتزويد المعنيين بالوثائق والمستندات والمعلومات اللازمة، وخلافها)، ومتابعة سجل الدوام اليومي وإغلاقه، ومتابعة جميع شؤونهم من مباشرة عمل وإخلاء طرف وندب والإجازات بأنواعها وغيرها من الإجراءات الوظيفية.","ضمان التنفيذ الفعال لخطة التقنية المعلوماتية في المدرسة، والمساهمة في ضمان تفعيل الحد الأدنى من منصات تقنية المعلومات المعتمدة في المدرسة وضمان استمراريتها واستثمارها بالشكل الأمثل.","الإشراف على عملية جمع البيانات لتقييم أداء الخدمات المساندة بالمدرسة وعملياتها وتقديم التقارير اللازمة لمدير المدرسة.","الإشراف على صيانة المدرسة والمحافظة على مرافقها.","الإشراف على مصادر التعلم ومتابعة تقديم خدماتها لمنسوبي المدرسة وتعزيز قدرة المكتبة لدعم جميع البرامج والتخصصات.","العمل على ضمان توفر الكتب والمصادر المناسبة للعملية التعليمية في مكتبة المدرسة والتواصل مع الجهات ذات العلاقة لتأمين الاحتياج إن وجد.","الإشراف على مختبرات ومعامل المدرسة ومتابعة سلامتها وتقديم الخدمات بالشكل المطلوب.","العمل على توفر المواد المختبرية وأجهزة الحاسب الكافية والتي تدعم تحقيق أهداف العملية التعليمية، والتواصل مع الجهات ذات العلاقة لتأمين الاحتياج إن وجد، والإشراف على إتلاف المواد المختبرية وفق التعليمات المنظمة لذلك.","تحديد احتياجات المدرسة من أجهزة الأمن والسلامة.","التنسيق مع الجهات المختصة لعقد برامج وورش عمل لمنسوبي المدرسة فيما يخص الأمن والسلامة، لتوعيتهم وتدريبهم بإجراءات السلامة وتعريفهم بوسائل الوقاية الواجب اتخاذها في حينه.","رصد الحالات الطارئة في نظام البلاغات.",rl,ll,"الإشراف على عمليات إدارة المرافق المدرسية (المستودع، المقصف، ...) وفق التعليمات المنظمة لذلك.","القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته."]},{id:"teacher",title:"المعلم (يشمل المعلم الخبير والمتقدم والممارس)",page:35,link:["يرتبط بوكيل المدرسة للشؤون التعليمية."],goal:"الإسهام في بناء شخصية الطالب بكافة جوانبها والارتقاء بمستواه التربوي والتعليمي من خلال توفير بيئة تعليمية وتعلمية محفزة (جميع الرتب التعليمية)، ودعم المعلمين في تحسين عملية التعليم والتعلم (المعلم المتقدم والخبير)، وتطوير الممارسات الإبداعية والمبتكرة التي تحسن من عملية التعليم والتعلم (المعلم الخبير).",qualifications:["شهادة تربوية جامعية أو أعلى تتناسب مع التخصص المطلوب.","الكفايات: المهارات التقنية، التفكير المرن، الانتماء، الإنجاز، تطوير الذات."],tasks:["تعزيز قيم الانتماء والمواطنة والاعتزاز بالدين الإسلامي والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة التي تعمل على تنمية الاعتزاز بالدين والولاء للملك والانتماء للوطن.","احترام الطالب ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.","دعم أهداف المدرسة مع تحديد فرص التحسين وتقديم توصية بشأنها لمدير المدرسة ومقدمي خدمات دعم التميز المدرسي.","تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.","تحديد مشاكل الطلاب، وطلب الدعم/المشورة من الأطراف المعنية عند الحاجة.","المشاركة في إعداد البحوث التخصصية أو التربوية أو الاستفادة من نتائج أبحاث تخصصية أو تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.","تصميم تدريس المواد المسندة إليه للطلاب في المدرسة حضوريًا أو عن بعد باستخدام استراتيجيات تعليم وتعلم حديثة ومتنوعة وتعمل على تنمية القدرة على التفكير والإبداع لدى الطلاب.","تفعيل التعليم الإلكتروني بقنواته المختلفة، وتطبيق ممارساته التعليمية بما يتناسب مع احتياجات الطلاب ورفع جودة العملية التعليمية، ومتابعة التطبيقات في المنصات المعتمدة.","إعداد خطة العمل الفصلية والأسبوعية واليومية، مع استحضار أهداف وعناصر المنهج للمواد المسندة إليه، لضمان التغطية الكاملة لهذه المناهج.","تقييم مستوى الطلاب بشكل مرحلي، وتفعيل جميع أدوات التقويم المتنوعة، وقياس نواتج التعلم للمادة التي يتم تدريسها، لضمان استيعابهم للمادة وفق نواتج التعلم، ووضع خطط علاجية لمعالجة نقاط ضعف الطلاب، وإعداد مواد إثرائية داعمة للمستويات المتقدمة.","تهيئة الطلاب وإعدادهم للمشاركة في الاختبارات الوطنية والدولية.","إعداد التكليفات والأنشطة والمهام الأدائية والاختبارات وفق الضوابط المعتمدة لذلك، وتصحيحها والعمل على تحديد الاحتياجات الفردية للطالب لفهمها.","تقديم تقييم وتغذية راجعة بناءة وبشكل منتظم تتوافق مع مستويات الطلاب لزيادة التحصيل الدراسي.","تقديم المشورة والتعاون مع المسؤولين ووكيل الشؤون التعليمية والمعلمين حول إعداد وتطوير المقررات، وأدوات التدريس، وإطار التعلم، وبرامج التدريس، وأساليب التدريس والتقييم وتحديد أولويات الرعاية.","التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وبما يقدمونه من خبرات.","الحفاظ على النظام والانضباط بين الطلاب وفقًا للسياسات المدرسية لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.","تفعيل المختبرات والمعامل ومصادر التعلم لتنمية مهارات التعلم لدى الطلاب.","الاستخدام الفعال للأجهزة والوسائل التعليمية ذات الصلة وتقديم طلب صيانة لها (آلات العرض، النظام السمعي/المرئي (الفيديو)...إلخ) والاحتياجات الأساسية وذلك لحماية جميع الممتلكات داخل المدرسة والتأكد من استخدامها على النحو الأمثل.","التخطيط للأنشطة الصفية واللاصفية من قبل المعلم الخبير (إن وجد)، ومشاركة المعلم الممارس والمعلم المتقدم في الإعداد والتنفيذ لهذه الأنشطة مثل الاجتماعات وبرامج التطوير المهني داخل المدرسة (مجتمعات التعلم المهني) والنمو المهني المفتوح (التخصصية والتربوية) خارج المدرسة، والتي تتعلق بالمتعلمين، المقررات الدراسية أو التنظيم المدرسي.","التنمية الذاتية علميًا ومهنيًا وتربويًا، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة أو مقدم خدمات دعم التميز المدرسي المختص وفق التنظيم والوقت المحددين.","المشاركة في تنمية زملاء العمل علميًا ومهنيًا وتربويًا، وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.","التواصل المستمر مع أولياء الأمور بالتعاون مع الموجه الطلابي، لاطلاعهم وتعريفهم بمستوى أبنائهم وتسليط الضوء على أي جوانب تستدعي الاهتمام وبناء شراكات مجتمعية مع مؤسسات المجتمع.","تنفيذ أنشطة المدرسة التعليمية/التعليمية المساندة ضمن الإمكانيات المحددة.","إعداد تقرير يتضمن تفاصيل الأنشطة والإنجازات والمعوقات أثناء تنفيذ مهامه كمعلم.","تفهم الخصائص النفسية للمرحلة العمرية التي يقوم بتدريسها والاجتماعية للكبار أو خصائص المرحلة.","القيام بأعمال المناوبة والإشراف على الطلاب قبل بداية الدوام الرسمي بـ 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته. والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع، وسد العجز الطارئ وفق توجيه إدارة المدرسة.","القيام بأي مهام يكلف بها من قبل مدير المدرسة تتناسب مع مهامه / مؤهلاته."]},{id:"teacher-assistant",title:"مساعد معلم",page:37,link:["يرتبط بوكيل المدرسة للشؤون التعليمية."],goal:"مساعدة المعلم في إدارة عمليات التعليم والتعلم للطلاب، وضبط الفصل، بهدف تحسين نواتج التعلم، وتحقيق أهداف المدرسة.",qualifications:["ثانوية عامة فأعلى.","دبلوم لا تقل مدته عن عام دراسي واحد في أحد التخصصات المناسبة لمجال العمل في هذه الرتبة."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، والمشاركة في متابعة البرامج والأنشطة الخاصة بذلك.","مساعدة المعلم في ضبط الفصل الدراسي، والحفاظ على النظام والانضباط بين الطلاب وفقًا لسياسات المدرسة، وإكمال أداء مهامه المنصوص عليها في حال غياب المعلم لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.","مساعدة المعلم في تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.","العمل مع المعلم في تنظيم الأنشطة التعليمية داخل الفصل وفي الأنشطة اللامنهجية داخل المدرسة وخارجها، والمشاركة في تنفيذها تحت إشراف المعلم.","مساعدة معلم المادة في متابعة تنفيذ الخطط التعليمية الخاصة بكل طالب، وفق توجيهات المعلم.","تكثيف المتابعة مع الطلاب ذوي المستوى التحصيلي المنخفض ليتمكنوا من مسايرة زملائهم، وفق توجيهات المعلم.","المساعدة في إعداد المواد التعليمية وتحضير بعض الأدوات الخاصة بالصف الدراسي، وتجهيز الوسائل التعليمية اللازمة للحصة الدراسية.","توزيع المواد التعليمية مثل الاختبارات والواجبات المنزلية وجمعها، والمساعدة في رصد/وضع الدرجات والنتائج، ومتابعة مستوى التقدم لدى طلاب الفصل.","يساعد المعلم في إعداد خطة الدرس، وإعداد المراجع، والخرائط، والنماذج والرسوم البيانية، وتجهيز السبورة، ولوحة الإعلانات وتسجيل الحضور والغياب للطلاب في الحصة.","القيام بأعمال المناوبة والإشراف اليومي على الطلاب قبل بداية الدوام الرسمي بـ 15 دقيقة وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته."]},{id:"activity-leader",title:"رائد النشاط",page:45,link:["يرتبط بوكيل المدرسة لشؤون الطلاب."],goal:"تنفيذ خطة النشاط الطلابي واكتشاف قدرات الطلاب وميولهم والإسهام في بناء شخصية الطلبة المتكاملة ليكونوا فاعلين في مجتمعهم من خلال التدريب على المهارات الحياتية ومن خلال الأنشطة (الفنية، الاجتماعية، الثقافية، الرياضية، العلمية، الكشفية ...).",qualifications:["شهادة جامعية."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","دعم الأهداف التعليمية من خلال الأنشطة المدرسية وتحديد فرص التحسين وتقديم التوصية للمسؤولين.","تحقيق أهداف ومؤشرات الأداء للأنشطة والفعاليات الرئيسية حسب الخطة التشغيلية للمدرسة.","تحديد الصعوبات المتعلقة بتنفيذ الأنشطة والبرامج الطلابية ذات العلاقة بالنشاط الطلابي، والعمل على تجاوزها قدر الإمكان (داخل المدرسة)، وطلب الدعم/المشورة عبر إدارة المدرسة من الجهات ذات العلاقة عند الضرورة.","اكتشاف قدرات وميول واحتياجات الطلاب (غير التعليمية) بكفاءة عالية فيما يتعلق بمجال اختصاصه ومن خلال المعلمين المختصين.","الإشراف على تنفيذ الخطة التشغيلية للأنشطة الطلابية والبرامج المعدة لذلك بما فيها حصص النشاط عبر منصة التعليم الإلكتروني والتعليم عن بعد المعتمدة في الوزارة (مدرستي)، بما يتفق مع الأنظمة واللوائح المنظمة لذلك، وتوثيقها، وتفعيل الاستبانات التي تقيس مدى تحقق برامج النشاط وتحليلها.","التخطيط للأنشطة والبرامج ذات العلاقة قبل بداية الفصل الدراسي وفق الأسابيع الدراسية المعتمدة، وضمان مناسبتها للمرحلة العمرية المستهدفة، وحسب الإمكانيات والموارد المتاحة وشمولها للجانب التطويري للطلاب.","الإشراف على مشاركة الطلاب في إعداد الخطة التشغيلية للأنشطة الطلابية والبرامج المعدة لذلك.","تنفيذ أنشطة المدرسة بما يتوافق مع الميزانية التشغيلية المحددة لها وفق المستندات النظامية المنظمة لذلك.","المشاركة في تقييم ومتابعة عملية الموافقة على تشكيل الأندية (إن وجدت) والتحقق من تلبيتها لمتطلبات واهتمامات الطلاب.","تفعيل المشاركات المدرسية والطلابية في المنصات العامة المخصصة لذلك، وتفعيل مشاركة الطلاب في الأنشطة، وتطوير مجموعة واسعة من المهارات الجديدة ذات الصلة تتناسب مع خطة وأهداف الوزارة.","توجيه بعض برامج النشاط للمعلمين وأولياء الأمور والمجتمع المحلي، وتعزيز العلاقات الإيجابية بين المدرسة والأسرة والمجتمع باعتبارها مؤسسات تربوية تؤثر في الطالب.","إعداد تقرير يتضمن تفاصيل الأنشطة والإنجازات والمعوقات أثناء تنفيذ المهام المعينة (أو المطلوبة)، والرفع به لوكيل شؤون الطلاب.","التأكد من تطبيق الاشتراطات النظامية والأمنية قبل تنفيذ برامج النشاط الصفية وغير الصفية.","تقديم الدعم للمتميزين في برامج النشاط من المعلمين وأولياء الأمور والطلاب والرفع للجنة الإدارية/وكيل المدرسة لشؤون الطلاب لمنحهم تكريمهم من قبل مدير المدرسة.","العمل بشكل وثيق مع المعلمين ودعمهم في تنفيذ الأنشطة اللاصفية.","تنسيق جميع الأنشطة اللاصفية في المدرسة، وتوفير أساسياتها ذات الصلة، ومرافق التدريب والتوجيه لضمان إعطاء فرص متكافئة للطلبة حسب الميول والقدرات.","توجيه تنظيم الأحداث المدرسية للأنشطة والبطولات من أجل رفع مستوى المشاركة والاهتمام بالأنشطة بين الطلاب.","التواصل مع المدارس الأخرى في المنطقة عبر طرق التواصل المعتمدة للمشاركة في الأحداث الرياضية المدرسية، بعد موافقة مدير المدرسة.","القيام بأعمال المناوبة والإشراف اليومي على الطلاب قبل بداية الدوام الرسمي بـ 15 دقيقة وبعد نهايته وحضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","متابعة وتقييم كافة البرامج بدقة والحرص على عدم احتوائها على ما يخالف التعليمات.","تفعيل دليل الشراكات وفق الدليل المنظم لذلك.","تأصيل حب التطوع في نفوس الطلاب، وابتكار واستحداث مجالات ونشاطات تطوعية مع الطلبة لخدمة المجتمع.","العمل على تأهيل الطالب للمسابقات والمشاركات الوطنية والإقليمية والدولية، والاستعانة بالجهات ذات الاختصاص للمساعدة في ذلك.","القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته."]},{id:"counselor",title:"الموجه الطلابي",page:47,link:["يرتبط بوكيل المدرسة لشؤون الطلاب."],goal:"تقديم الدعم النفسي والاجتماعي للطالب، ليفهم ذاته ويعرف قدراته ويبني إمكاناته، ويتمكن من حل مشكلاته بما يحقق له التوافق النفسي والاجتماعي والمهني والتربوي، بما يعزز أهداف التعليم والتعلم ويحسن نواتجه.",qualifications:["شهادة جامعية (علم نفس / علم اجتماع / خدمة اجتماعية)","أو بكالوريوس تربوي + دبلوم توجيه وإرشاد أو ماجستير فأعلى في التخصص."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","إعداد الخطة السنوية للتوجيه الطلابي في المدرسة، وفقًا لما هو معتمد لذلك، وتوزيع الأسابيع الدراسية مع مراعاة تفعيلها وتنفيذها حسب التعاميم المنظمة لذلك.","حصر ومتابعة المشكلات السلوكية والحالات الخاصة (تربوية – نفسية – اجتماعية)، وتخطيط التدخلات التربوية المناسبة.","متابعة حالات الطلاب متكرري الغياب والتأخر الصباحي والتأخر نهاية اليوم الدراسي، واتخاذ الإجراءات التصحيحية اللازمة، بالتنسيق مع وكيل شؤون الطلاب.","متابعة مستويات الطلاب التحصيلية (المعيدين والمتأخرين دراسيًا ومتكرري الرسوب) والمساهمة في تحسين أداء الطلاب وزيادة نواتج تعلمهم من خلال وضع البرامج المحفزة والعلاجية المناسبة لهم بعد دراسة وتحليل وتفسير نتائج كل فترة مع وجود مقارنة مجدولة قبل وبعد البرنامج العلاجي.","متابعة التحسن في نواتج تعلم الطلاب المعيدين والمتأخرين دراسيًا ومتكرري الرسوب، لمعرفة جدوى الإجراءات المتخذة، وتقديم التقارير إلى لجنة التحصيل الدراسي بالتنسيق مع معلمي المواد.","تفعيل برامج التوجيه الطلابي الوزارية في مستوياتها (الإنمائية والوقائية والعلاجية) وبرامج الخطة التشغيلية لإدارة التعليم، بما يتواءم مع واقع تشخيص المدرسة، والعمل على تطويرها وتفعيل البرامج الثقافية للطلاب للتعريف بمهارات المستقبل ومتطلباته.","دراسة حالات الطلاب المعيدين والمتأخرين دراسيًا ومتكرري الرسوب، واقتراح الإجراءات المناسبة بالتنسيق مع معلمي المواد، وتقديم تقرير إلى لجنة التحصيل الدراسي لإقرار التوصيات المناسبة، ومتابعة تنفيذ التوصيات بعد اعتمادها من مدير المدرسة.","تفعيل قرارات وتوصيات لجنة التوجيه الطلابي في المدرسة ومتابعة تنفيذها.","تفعيل المجلس الطلابي وفق الأدلة المنظمة لذلك.","عقد جلسات توجيه فردي وجمعي مع فتح ملفات دراسة حالة فردية أكثر تفصيلًا إذا لزم الأمر.","تقديم التوجيه الجمعي لعموم الطلاب فيما يتعلق بالقضايا الاجتماعية الهامة بالتعاون مع المعلمين وأولياء الأمور.","تعريف الطلبة بسوق العمل ومتطلباته ومساعدتهم على تحديد أهدافهم المهنية المستقبلية وإعدادهم لسوق العمل من خلال تطوير مهاراتهم الشخصية والمهنية بما يتناسب مع المرحلة الدراسية وتفعيل المناشط والمناسبات المرتبطة بها.","الاستفادة من الأنشطة المدرسية بما يخدم عملية التوجيه الطلابي.","الإشراف على الطلاب ومرافقتهم إلى المعارض المهنية والمؤتمرات الدولية وتقديم التوجيه ما أمكن.","إدارة وتنظيم لقاءات أولياء أمور الطلاب وإعداد مجالس أولياء الأمور بالتنسيق مع وكيل شؤون الطلاب وأصحاب العلاقة والمشاركة في فعاليات شراكة الأسرة مع المدرسة.","تعزيز الصحة النفسية لدى الطلاب بكافة الوسائل والأساليب الإرشادية المتاحة، بمشاركة الموجه الصحي.","اكتشاف قدرات وميول الطلاب وتنميتها وتوجيههم للتخصصات المناسبة لهم وتنمية الاتجاه الإيجابي لهم نحو المهن، بالتنسيق مع معلم الموهوبين (إن وجد).","تفعيل قنوات التعليم الإلكتروني للطلاب في تطبيق ممارسات التوجيه الطلابي بكافة جوانبها التربوية والنفسية والاجتماعية وغيرها بما يتناسب مع احتياجات الطلاب ويسهم في رفع جودة نواتج التعلم السلوكية.","القيام بأعمال المناوبة والإشراف اليومي على الطلاب قبل بداية الدوام الرسمي بـ 15 دقيقة وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","تنظيم برنامج استقبال الطلاب المستجدين في المرحلة الابتدائية وبرنامج التهيئة الإرشادية في الصفوف والمراحل الانتقالية وللطلبة المنتقلين للمدرسة.","تعريف الطلاب باختبارات قياس والاختبارات التحصيلية وتهيئتهم للاستعداد لها.","توعية منسوبي المدرسة بخصائص نمو الطلاب ومراعاة احتياجاتهم ومطالب نموهم في المجتمع المدرسي والمحلي، بمشاركة الموجه الصحي.","رعاية الطلاب المتفوقين دراسيًا والمتميزين سلوكيًا والرفع لتكريمهم من قبل مدير المدرسة وفق الأنظمة المعدة لذلك، بالتنسيق مع معلم الموهوبين (إن وجد).","تطبيق فنيات التوجيه النفسي وأساليب تعديل السلوك لمساعدة الطلاب الذين لديهم مشكلات سلوكية ومراعاة خصائص نمو الطلاب واحتياجاتهم ومطالب نموهم.","إعداد التقرير الختامي للبرامج والخدمات التوجيهية متضمنًا التقويم والمرئيات حول الخدمات المقدمة، ورفعها للجنة التوجيه الطلابي.","رفع وتوثيق أعمال وبرامج وخدمات رعاية الطلاب ودعمهم على برنامج نور.","القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته."]},{id:"health-guide",title:"الموجه الصحي",page:49,link:["يرتبط بوكيل المدرسة لشؤون الطلاب."],goal:"العمل على إيجاد بيئة صحية مناسبة في المدرسة، من خلال توعية الطلاب صحيًا، وتقديم الإسعافات الأولية اللازمة لهم، بهدف توفير بيئة صحية تعزز تحقيق أهداف المدرسة وتحسين نواتج التعلم.",qualifications:["شهادة جامعية.","(دورات إسعافات أولية متقدمة)."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","إعداد خطة الصحة المدرسية وتنفيذ البرامج والمناسبات الصحية المعتمدة في خطة الشؤون الصحية المدرسية وتسجيل متطلباتها والتقارير اللازمة لها في حساب الموجه الصحي على نظام نور.","التوعية الصحية والتثقيف الصحي في المجتمع المدرسي، وتفعيل التوصيات المتعلقة بالصحة المدرسية في المدرسة.","تلقي ملاحظات منسوبي المدرسة عن المشكلات الصحية لدى الطلاب أو في البيئة المدرسية والتنسيق لاتخاذ الإجراء المناسب تجاهها.","الإشراف على عمل الإسعافات الأولية للحالات الطارئة في المدرسة قبل وصول المختصين.","تنفيذ التعليمات والتعاميم والخطط من مشرف الشؤون الصحية وإعداد الخطوات التنفيذية لها، ورفع التقارير الدورية له.","مساعدة ممرض المدرسة (إن وجد) في متابعة الحالة الصحية للطلاب ومتابعة السجلات الصحية للطلاب على (النظام الإلكتروني) ومتابعة المحالين بأعراض مرضية للمركز الصحي.","مشاركة ممرض المدرسة (إن وجد) في تنفيذ البرامج الصحية بالمدرسة.","تفقد البيئة الصحية المدرسية.","التعاون مع منسوبي المدرسة في تفقد النظافة الشخصية للطلاب ومتابعة سلوكياتهم الصحية والعمل على تعديلها.","المساهمة مع الموجه الطلابي في توعية منسوبي المدرسة بخصائص نمو الطلاب ومراعاة احتياجاتهم ومطالب نموهم في المجتمع المدرسي والمحلي.","حصر ودراسة ومتابعة حالات الطلاب الصحية، وتقديم الخدمات المناسبة لهم بداية العام الدراسي.","إعداد التقرير الختامي للبرامج والخدمات الصحية في ضوء خطة الصحة المدرسية المعتمدة متضمنًا التقويم والمرئيات حول الخدمات المقدمة.","القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته."]},{id:"disability-teacher",title:"معلم ذوي الإعاقة",page:38,link:["يرتبط بوكيل المدرسة للشؤون التعليمية."],goal:"الإسهام في بناء شخصية الطالب ذوي الإعاقة بكافة جوانبها والارتقاء بمستواه التربوي والتعليمي، ودعم المعلمين في تحسين عملية التعليم والتعلم، وتطوير الممارسات الإبداعية والمبتكرة التي تحسّن من عملية التعليم والتعلم (يشمل المعلم الخبير والمتقدم والممارس).",qualifications:["شهادة جامعية أو أعلى في التربية الخاصة."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","احترام الطلاب ومعاملتهم معاملة تربوية تحقق لهم الأمن والطمأنينة وتنمي شخصياتهم، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.","تقييم مستوى الطلاب بشكل مرحلي، وقياس نواتج التعلم، لضمان استيعابهم للمادة التي يتم تدريسها، ووضع خطط علاجية لمعالجة نقاط ضعف الطلاب، وإعداد مواد إثرائية داعمة للمستويات المتقدمة.","تصميم وتدريس المواد المسندة إليه في المدرسة للطلاب ذوي الإعاقة (بأسلوب فردي أو مجموعات) حضورياً أو عن بعد باستخدام استراتيجيات تعليم وتعلم حديثة ومتنوعة وتعمل على تنمية القدرة على التفكير والإبداع لدى الطلاب.","إعداد خطة العمل الفصلية والأسبوعية واليومية، مع استحضار عناصر المنهج المسندة إليه، لضمان التغطية الكاملة لهذه المناهج.","تولي مسؤولية غرفة المصادر لذوي الإعاقة (إن وجدت) في المدرسة والعمل على تحديد العجز من التجهيزات المطلوبة لها ومن التجهيزات المطلوبة للمبنى المدرسي لحالات الطلاب ذوي الإعاقة ورفعها لوكيل الشؤون المدرسية.","المشاركة في إعداد الجداول الدراسية لكل طالب من ذوي الإعاقة بالتعاون والتنسيق مع المعنيين في المدرسة.","التواصل مع أولياء الأمور وتوعيتهم وتفعيل دورهم في المشاركة الإيجابية في المدرسة بالتعاون مع الموجه الطلابي.","التنسيق مع الجهات ذات العلاقة داخل وخارج المدرسة فيما يتعلق بالطلاب ذوي الإعاقة.","تنظيم السجلات والوثائق ذات العلاقة بذوي الإعاقة وفق الأسس الفنية المتعارف عليها.","تقديم الدعم للمهنيين التعليمين أو اللجان ذات العلاقة في الأمور التي تخص الطلاب ذوي الإعاقة من طرق التدريس والاستراتيجيات التعليمية وأساليب التعامل مع الطالب وأساليب تأدية الاختبارات وغيرها.","تنفيذ التطبيقات الصفية ومراجعة نواتج التعلم بمعدل عشر دقائق للحصة الواحدة.","متابعة أعمال الطلاب الصفية والواجبات المنزلية وتصحيحها، وتقديم التغذية الراجعة لهم.","إعداد وتنفيذ البرامج التربوية الفردية والخاصة بالطلاب ذوي الإعاقة ومتابعة نتائجها والعمل على تطويرها.","إعداد التقارير الدورية عن مستوى الطلاب ذوي الإعاقة وتزويد أولياء أمورهم بها بعد اعتمادها من وكيل الشؤون التعليمية.","إعداد وتنفيذ الاختبارات للطلاب ذوي الإعاقة بالمشاركة مع ذوي العلاقة، حسب ما ورد في المذكرة التفسيرية للائحة تقويم الطالب.","إعداد البرامج الترفيهية والأنشطة الصفية واللا صفية وبرامج الصحة والسلامة وتفعيل مناسبات الإعاقة المحلية والإقليمية والعالمية بالتعاون مع الجهات المعنية في المدرسة وخارجها، بالتنسيق مع رائد النشاط.","القيام بأعمال المناوبة والإشراف على الطلاب قبل بداية الدوام الرسمي بـ 15 دقيقة الاصطفاف الصباحي وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته، والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 29 ساعة في الأسبوع.","تغطية حصص الانتظار والقيام بعمل معلم ذوي الإعاقة الغائب وسد العجز الطارئ في عددهم وفق توجيه إدارة المدرسة.","دراسة ومعالجة صعوبات التعلم وأسبابها لدى الطلاب اللذين يواجهون هذه المشكلة.","المشاركة في اعداد البحوث التخصصية أو التربوية أو الاستفادة من نتائج أبحاث تخصصية أو تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.","التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.","التنمية الذاتية علمياً ومهنياً وتربوياً، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، ووفق التنظيم والوقت المحددين.","تنمية زملاء العمل علمياً ومهنياً وتربوياً وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.","الالتزام بالنصاب التدريسي للرتب التعليمية حسب ما يشغلها، 18 حصة للمعلم الممارس، و16 حصة للمعلم المتقدم، و14 حصة للمعلم الخبير.","القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته."]},{id:"gifted-teacher",title:"معلم الموهوبين",page:40,link:["يرتبط بوكيل المدرسة للشؤون التعليمية."],goal:"الإسهام في بناء شخصية الطالب الموهوب بكافة جوانبها والارتقاء بمستواه التربوي والتعليمي من خلال توفير بيئة تعليمية وتعلمية محفزة، ودعم المعلمين في تحسين عملية التعليم والتعلم، وتطوير الممارسات الإبداعية والمبتكرة التي تحسّن من عملية التعليم والتعلم (يشمل المعلم الخبير والمتقدم والممارس).",qualifications:["شهادة جامعية (في التفوق والابتكار أو تخصص علمي + دورات في الموهبة والابتكار).","خبرة 5 سنوات فأكثر في التعليم."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","احترام الطالب ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.","تنفيذ الخطة التشغيلية لبرامج الموهوبين وفقاً للمعايير العلمية والضوابط التنظيمية المنصوص عليها.","المشاركة والتنسيق لترشيح الطلاب للمشروع الوطني للكشف على الموهوبين.","اختيار وترشيح الطلاب لبرامج الموهوبين داخل المدرسة وخارجها عن طريق مدير المدرسة وفق مخرجات المشروع الوطني للكشف على الموهوبين.","إعداد قاعدة بيانات للطلاب الموهوبين داخل المدرسة وتزويد قسم الموهوبين بنسخة منها، وربطها مع النظام.","متابعة أعمال الطلاب الصفية والمشاريع والأنشطة الإثرائية، وتقديم التغذية الراجعة لهم.","قياس نواتج التعلم في الحصص الدراسية واستيفاء النماذج المخصصة لذلك.","التنسيق مع الموجه الطلابي بالمدرسة؛ لتوفير الرعاية النفسية والاجتماعية المناسبة للطلاب الموهوبين.","تنمية مهارات التفكير والبحث العلمي لدى الطلاب الموهوبين التي تناسب اهتماماتهم وميولهم من خلال تقديم البرامج الإثرائية.","تغطية حصص الانتظار (بما لا يزيد عن حصتين في الأسبوع)، والقيام بعمل المعلم الغائب وسد العجز الطارئ في عدد معلمي الموهوبين وفق توجيه إدارة المدرسة.","القيام بأعمال المناوبة والإشراف على الطلاب قبل بداية الدوام الرسمي بـ 15 دقيقة الاصطفاف الصباحي وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته، والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","المشاركة في تقويم برامج الموهوبين في المدرسة باستخدام أدوات التقويم المعتمدة، وإبراز جميع أعمال ومنجزات الطلاب الموهوبين داخل المدرسة من خلال المعرض الختامي السنوي.","التواصل مع أولياء أمور الموهوبين فيما يخص شئون مواهبهم، والمشاركة في عضوية اللجان الخاصة بالموهوبين داخل المدرسة إن وجدت، مثل: لجنة تسريع الطلاب الموهوبين وغيرها من اللجان.","المشاركة في نشر ثقافة الموهبة والإبداع داخل المجتمع المدرسي والبيئة المحيطة، والبرامج الإثرائية والمسابقات التي ينفذها قسم الموهوبين في إدارة التعليم العامة.","حضور ورش العمل والاجتماعات الدورية والبرامج التدريبية لمعلمي الموهوبين وفق خطة قسم الموهوبين في إدارة التعليم العامة.",'ترشيح طلبة المدرسة للبرنامج الوطني للكشف عن الموهوبين عن طريق مدير المدرسة، والأولمبياد الوطني للإبداع العلمي "إبداع"، والمسابقات والفعاليات الأخرى المعتمدة في مجال الموهوبين.',"المشاركة في اعداد البحوث التخصصية أو التربوية أو الاستفادة من نتائج أبحاث تخصصية أو تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.","التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.","التنمية الذاتية علمياً ومهنياً وتربوياً، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، وفق التنظيم والوقت المحددين.","تنمية زملاء العمل علمياً ومهنياً وتربوياً وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.","إعداد تقرير ختامي سنوي عن البرامج المنفذة والدور الذي قام به داخل المدرسة، والعمل على رفع التوصيات على ما تم ملاحظته خلال العام؛ لتطوير وتجويد العمل وتحسينه لرفعها لقسم الموهوبين في إدارة التعليم العامة.","القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته."]},{id:"kindergarten-teacher",title:"معلمة رياض الأطفال",page:42,link:["ترتبط بوكيلة المدرسة للشؤون التعليمية."],goal:"الإسهام في بناء شخصية الطفل بكافة جوانبها والارتقاء بمستواه التربوي والتعليمي من خلال توفير بيئة تعليمية وتعلمية محفزة، ودعم المعلمين في تحسين عملية التعليم والتعلم، وتطوير الممارسات الإبداعية والمبتكرة التي تحسّن من عملية التعليم والتعلم (يشمل المعلم الخبير والمتقدم والممارس).",qualifications:["شهادة جامعية تخصص رياض أطفال.","الكفايات: المهارات الوظيفية التقنية، التفكير المرن، الانتماء، الإنجاز، تطوير الذات، ضبط النفس."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","احترام الطفل ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.","تنفيذ الخطة وفقاً للمعايير العلمية والضوابط التنظيمية المنصوص عليها.","التعامل مع الطفل بطريقة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي اهتماماته وخصائصه العمرية، وتغرس في نفسه حب التعلم والمعرفة، وتكسبه السلوك الإيجابي والتواصل الفعال مع المحيطين به، وتؤصل فيه الثقة بالنفس.","تقبل جميع الأطفال ومعاملتهم بعدالة وعدم التحيز واحترام الاختلافات بينهم في الشكل واللون والعرق والثقافة.","تفعيل منهج رياض الأطفال المعتمد والتخطيط للبرنامج الأسبوعي واليومي وتنفيذه، مع تطبيق الممارسات الملائمة نمائياً، والأنشطة والوسائل التعليمية التربوية المصاحبة، وتنمية جوانب الإبداع لدى الأطفال وتعزيزها.","تهيئة البيئة التعليمية، والاستعانة بالتقنية الداعمة، وإعداد الوسائل التعليمية والتخطيط لبناء أنشطة محفزة، واستثمار المواقف التعليمية بما يتوافق مع الخصائص النمائية للطفل وطبيعة المرحلة العمرية واحتياجاتها؛ لدعم العملية التعليمية من أجل تحقيق الأهداف التربوية المنشودة.","تقويم الطفل بشكل مستمر وقياس نواتج التعلم لديه ومتابعة تطور جوانب النمو المختلفة مع تقديم النتائج والتوصيات للجهات ذات العلاقة، وتقديم التغذية الراجعة لهم.","دراسة حالة الطفل في حال تطلب دعم أحد جوانب نمو الطفل أو ظهور مشاكل سلوكية بالتنسيق مع ذوي العلاقة، لإيجاد الحلول التربوية الملائمة.","التنسيق مع الموجه الطلابي بالمدرسة (إن وجد) وإدارة المدرسة لتوفير الرعاية النفسية والاجتماعية المناسبة للأطفال الموهوبين وللطلاب الذين لديهم مشكلات سلوكية لمتابعة دراسة حالتهم.","التبليغ عن الحالات الطارئة أو الخاصة، أو المرضية، واتباع الإجراءات النظامية عند الاشتباه بحالة عنف أو أي نوع من الإيذاء نحو الطفل حسب التعاميم المنظمة لذلك.","القيام بأعمال المناوبة والإشراف على الأطفال في الفصل الخاص به قبل بداية الدوام الرسمي بـ 15 دقيقة الاصطفاف الصباحي وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته، والمشاركة في الإشراف اليومي على الأطفال حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع، وسد العجز الطارئ وفق توجيه إدارة المدرسة.","مواكبة المستجدات وتنمية الذات، وتطوير الكفايات العلمية والمهنية والتربوية من خلال المشاركة في البرامج والأنشطة والدورات التربوية وورش العمل التي تطور المتطلبات الوظيفية.","متابعة الأطفال خلال فترات البرنامج اليومي للحفاظ على أمنهم وسلامتهم، وتوجيه سلوكهم بما يتناسب مع الخصائص النمائية للمرحلة.","تقويم جوانب العملية التعليمية (أنشطة المنهج، بيئات التعلم، الممارسات والاستراتيجيات، والمواد التعليمية) وتطوير النتائج؛ لتحقيق الأهداف ورفع مستوى جودة التعليم والتعلم.","بناء علاقة إيجابية مع أسر الأطفال، لدعم جوانب نموه وتلبية احتياجاته وتعزيز قدراته ومهاراته.","المشاركة في اعداد البحوث التخصصية أو التربوية أو الاستفادة من نتائج أبحاث تخصصية أو تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.","التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.","التنمية الذاتية علميا ومهنيا وتربويا، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، وفق التنظيم والوقت المحددين.","تنمية زملاء العمل علميا ومهنيا وتربويا وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.","المشاركة في تنظيم الفصل والملاعب الداخلية والخارجية.","القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته."]},{id:"disability-assistant",title:"مساعد معلم (ذوي الإعاقة)",page:44,link:["يرتبط بوكيل المدرسة للشؤون التعليمية."],goal:"مساعدة معلم ذوي الإعاقة في إدارة عمليات التعليم والتعلم للطلاب ذوي الإعاقة وضبط الفصل، بهدف تحسين نواتج التعلم، وتحقيق أهداف المدرسة.",qualifications:["ثانوية عامة فأعلى (يُفضل دبلوم جامعي أو أعلى في ذوي الإعاقة، لمدة عام على الأقل).","المعرفة بلغة الإشارة لتخصصات الإعاقة السمعية (فئة: الصم).","المعرفة بطريقة برايل لتخصصات الإعاقة البصرية (فئة: المكفوفين).","يُفضّل من لديه دورة تدريبية في التعامل مع ذوي الإعاقة.","يُفضّل من لديه دورة تدريبية في دعم السلوك الإيجابي (PBS)."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","مساعدة المعلم في ضبط الفصل الدراسي، والحفاظ على النظام والانضباط بين الطلاب وفقاً لسياسات المدرسة لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.","مساعدة المعلم في تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.","دعم معلم ذوي الإعاقة في التقييم لحالات الإعاقة.","القيام بأعمال المناوبة والإشراف اليومي على الطلاب قبل بداية الدوام الرسمي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","العمل مع المعلم في إعداد وتنظيم الأنشطة التعليمية داخل الفصل وفي الأنشطة اللامنهجية داخل المدرسة وخارجها، والمشاركة في تنفيذها تحت إشراف المعلم.","مساعدة معلم ذوي الإعاقة على إعداد الخطط التربوية الخاصة بكل طالب، ومتابعة تنفيذها وفق توجيهات المعلم.","مساعدة الطلاب أثناء مراجعتهم دروسهم، وتكثيف المتابعة للطلاب ذوي المستوى التحصيلي المنخفض ليتمكنوا من مسايرة زملائهم.","المساعدة في إعداد المواد التعليمية وتحضير بعض الأدوات الخاصة بالصف الدراسي، وتجهيز الوسائل التعليمية اللازمة للحصة الدراسية.","توزيع المواد التعليمية مثل الاختبارات والواجبات المنزلية وجمعها، والمساعدة في رصد/وضع الدرجات والنتائج، ومتابعة مستوى التقدم لدى طلاب الفصل ولدى الطلاب المستهدفين خاصة داخل الفصل.","المشاركة في الاجتماعات التي يحضرها أولياء أمور الطلاب لمناقشة أوضاعهم الدراسية والسلوكية.","تولي مسؤولية ضبط الفصل/الطلاب في حال غياب المعلم وإكمال أداء مهامه المنصوص عليها.","مساعدة المعلم في إعداد خطة الدرس، وإعداد المراجع، والخرائط، والنماذج والرسوم البيانية، وتجهيز السبورة، ولوحة الإعلانات وتسجيل الحضور والغياب للطلاب في الحصة.","مساعدة الطلاب ذوي الإعاقة على فهم الدروس والتعليمات التي يقدمها المعلم بالطريقة التي تتناسب مع نوع الإعاقة لديهم.","القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته."]},{id:"resources-keeper",title:"أمين مصادر التعلم",page:50,link:["يرتبط بوكيل المدرسة للشؤون المدرسية."],goal:"الإشراف على جميع العمليات والخدمات الخاصة بالمصادر لضمان تقديم الخدمات الخاصة بالبحث والدراسات والمراجع المناسبة لجميع المستفيدين لدعم جميع البرامج والتخصصات بالمدرسة.",qualifications:["شهادة جامعية.","(تقني/ إداري + دورات تقنية متقدمة)."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","تحديد وتقديم المقترحات التطويرية لوكيل شؤون الطلاب ولمقدم خدمات دعم التميز المدرسي على مصادر التعلم/المعامل لتحقيق ودعم أهداف المدرسة.","تحقيق أهداف ومؤشرات الأداء حسب مهامه ومسؤولياته على المصادر/المعامل.","تحديد المشكلات والبحث عن الحلول والدعم من الجهات المختصة عند اللزوم.","المشاركة في تفعيل المناسبات الثقافية والتربوية والوطنية وتنمية الاعتزاز بالدين والولاء للملك والانتماء للوطن.","تطوير الخطط والإجراءات للاستفادة من المصادر/المعامل في تحقيق الأهداف العامة للتعليم والتعلم.","تفعيل إجراءات نظام إعارة وترجيع مكونات المصادر المدرسية لضمان جودة وكفاءة ومعايير الخدمات المقدمة.","تدريب المستفيدين من مصادر التعلم على أفضل الطرق للاستخدام الأمثل لمرافق المصادر/المعامل المدرسية من أجل المحافظة على مستلزماتها ومرافقها مع توفير البيئة المكانية المناسبة.","إعداد خطة عامة وجدول عمل يومي أو أسبوعي خاص بمصادر التعلم/المعامل.","الاتصال مع المستفيدين في المدرسة من أجل توفير جميع المتطلبات الخاصة بهم باستخدام غرفة مصادر التعلم، وتحديد الاحتياجات مثل الكتب، مجلات، دوريات وأي خدمات أخرى مثل أجهزة عرض وشبكة اتصال حاسوبية وما إلى ذلك.","العمل على إيصال أدوات المصادر/أجهزة المعامل من خلال المشاركة في مراجعة وتسليم الطلبات الخاصة بالمصادر/أجهزة المعامل واستلامها.","التأكد بأن جميع المواد والمحتوى المعرفي المتوفر بالمصادر متوافق مع الشروط والأنظمة واللوائح المنظمة لذلك من حيث مناسبته للفئة العمرية للطلاب وثقافة المملكة العربية السعودية.","إدارة إجراءات استعارة الكتب وإعادتها، وإرسال رسائل تذكيرية للمتأخرين لضمان التزام الجميع بسياسات وإجراءات المصادر.","إدارة وتنظيم وترتيب وترميز وتصنيف موارد المعلومات الالكترونية والمطبوعة على حد سواء، وإدخالها في النظام المخصص لذلك وفهرسة وتصنيف المواد والكتب ومصادر التعلم المختلفة الخاصة بالمكتبة، لتسهيل عملية تداولها والوصول إليها، وإدارة عملية إعارتها.","القيام بأعمال المناوبة والإشراف اليومي على الطلاب قبل بداية الدوام الرسمي وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","مساعدة المعلمين والطلاب في المعمل (عند الحاجة) إذا تطلب الأمر.","تهيئة وتجهيز المعامل والتأكد من جاهزيتها وتنظيمها وترتيبها ومتابعة نظافتها قبل وبعد استخدامها.","القدرة على تحديد المشاكل وطلب الدعم/المشورة من الأطراف المعنية عند الضرورة في مجال عمله وتخصصه.","استكشاف أخطاء الأجهزة والمواد التعليمية وإصلاحها قدر المستطاع عند وجود مسائل أو مشكلات فنية متعلقة بها من أجل تحديد وإجراء الحلول المناسبة.","القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته."]},{id:"lab-assistant",title:"محضر مختبر",page:52,link:["يرتبط بوكيل الشؤون المدرسية."],goal:"الإشراف على إعداد وتشغيل الأجهزة والمواد التعليمية في المختبرات المستخدمة في المدرسة لضمان توفر الدعم اللازم للقيام بمهام التدريس العملي أو أي أنشطة مدرسية أخرى تتم داخل المختبر.",qualifications:["دبلوم تحضير مختبرات.","أو بكالوريوس علوم/ إداري ودورات في المختبرات."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","دعم أهداف المدرسة من خلال توفير بيئة مختبرية آمنة وتحديد فرص التحسين وتقديم التوصية بذلك لوكيل الشؤون المدرسية ولمقدم خدمات دعم التميز المدرسي.","تحقيق الأهداف ومؤشرات الأداء الرئيسة حسب مهامه ومسؤولياته.","القدرة على تحديد المشاكل وطلب الدعم/المشورة من الأطراف المعنية عند الضرورة في مجال عمله وتخصصه.","إعداد وتنظيم الأجهزة والمواد التعليمية كما هو متطلب للدروس.","تهيئة وتجهيز المختبرات وتنظيمها وترتيبها، ومتابعة نظافتها قبل وبعد استخدامها.","ضمان تجهيز وتسليم الأجهزة المطلوبة من قبل المعلمين ووضعها في المكان المخصص.","ترتيب وتنظيف الأجهزة عند الانتهاء من استعمالها وتخزينها بصورة سليمة وآمنة.","الحفاظ على الأجهزة والمواد التعليمية، وتخزينها بشكل صحيح، وإجراء إصلاحات بسيطة إن كان ذلك ممكناً، وترتيب المواد الكيميائية بطريقة منظمة وآمنة.","إعداد برنامج متكامل لنشاط المختبرات حسب اليوم والحصة والموضوع مع جدول متابعة تنفيذ التجارب للمعلم.","مساعدة المعلمين والطلاب في المختبر (عند الحاجة) إذا تطلب الأمر.","إعداد اللوحات والنشرات الإرشادية باستخدام الأدوات والأجهزة والمواد في المعامل والمختبرات، ومراجعة فحوصات المخزون بشكل منتظم.","استكشاف مشاكل الأجهزة والمواد التعليمية والعمل على إصلاحها ومعالجتها قدر الإمكان، والتواصل مع الجهات ذات الاختصاص عند العجز عن ذلك.","القيام بأعمال المناوبة والإشراف اليومي على الطلاب قبل بداية الدوام الرسمي وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","حفظ المواد الكيميائية/والأجهزة في الأماكن المخصصة لها، والتأكد من مدى سلامة حفظها ومن صلاحية انتهائها (للمواد الكيميائية).","المساهمة في تنفيذ أنشطة المدرسة المتعلقة بتخصص عمله وفق إمكاناتها.","إعداد تقرير يتضمن تفاصيل الأنشطة، والإنجازات والمعوقات أثناء تنفيذ المهام المطلوبة.","الالتزام بكافة إجراءات السلامة في المختبر ومتابعة تنفيذها.","القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته."]},{id:"secretary",title:"المساعد الإداري (سكرتير)",page:53,link:["يرتبط بمدير/وكيل المدرسة حسب موقعه التنظيمي."],goal:"تقديم الدعم الإداري للمدير/الوكيل، وأداء المهام الإدارية والمساندة في المدرسة.",qualifications:["دبلوم بعد الثانوي أو أعلى.","شهادة حاسب آلي (تقنية) والمتعلقة بالبرامج المكتبية.","الكفايات: إدارة الوقت، الاتصال الفعال، المهارات التقنية."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","أداء المهام والأنشطة المكتبية والإدارية الأساسية والسكرتارية للمدرسة وتنفيذ توجيهات المدير /الوكيل وتعليماته بشأنها، كتنسيق الملفات، وتصوير الأوراق، وإدخال واسترجاع البيانات والوثائق ومعالجة وتحرير النصوص.","أداء مهام الاتصالات الإدارية وإرسال واستلام الرسائل والطرود وفرزها وتوجيهها إلى الشخص المعني، وفقًا لتوجيهات المدير/الوكيل.","تبليغ ما يصدر من المدير / الوكيل من تعليمات لموظفي المدرسة.","تقديم الدعم للعمليات المدرسية التنظيمية والإدارية اليومية متى ما تطلب ذلك.","تنظيم اجتماعات المدرسة/اللجنة وإدارة وتوثيق محاضرها، حسب توجيه المدير/الوكيل.","إعداد جداول الأعمال ونشرها وفقًا للتوجيهات من المدير / الوكيل.","المساعدة في جمع وتنظيم المعلومات وإعداد التقارير وفق توجيه المدير/الوكيل.","إعداد التقارير إلكترونيا وورقيا وفق توجيه رئيسه المباشر.","استلام وتجهيز ملفات الطلاب المستجدين والمنقولين من المدرسة وإليها، وإنهاء جميع المخاطبات والإجراءات، وتنظيم ملفات الطلاب والحرص على اكتمال جميع الوثائق المطلوبة.","تسجيل وتسليم العهد لجميع العاملين في المدرسة واستلامها نهاية العام الدراسي، وتنظيم ملفاتهم وتزويدها بجميع المستجدات التي تطرأ على الموظفين.","القيام بأخذ حضور وتأخر وغياب الطلاب عن المدرسة.","إدارة وتنفيذ أعمال مستودع المدرسة، واستلام وحفظ المواد والتجهيزات والكتب المدرسية في الأماكن المخصصة لذلك.","التواصل مع أولياء الطلاب باستخدام الوسائل المتاحة في حال تأخر وغياب الطلاب عن المدرسة.","القيام بأعمال المناوبة والإشراف اليومي على الطلاب قبل بداية الدوام الرسمي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامه/مؤهلاته."]},{id:"registrar",title:"مسجل معلومات",page:54,link:["يرتبط بوكيل المدرسة لشؤون الطلاب."],goal:"إدخال وحفظ واسترجاع جميع البيانات والمعلومات المتعلقة بالمدرسة عبر الأنظمة الحاسوبية المستخدمة.",qualifications:["شهادة ثانوية + دبلوم في الحاسب الآلي."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","تسجيل المعلومات والبيانات المتعلقة بالمدرسة في الحاسب الآلي وحفظها وفق نظام التسجيل المعتمد.","تسجيل طلاب الصف الأول الابتدائي بنظام نور في حال عدم قدرة ولي أمر الطالب على التسجيل.","إدخال تأخر وغياب الموظفين في المدرسة وفق البرنامج المخصص لذلك.","إدخال تأخر وغياب الطلاب اليومي وفق البرنامج المخصص لذلك.","تجهيز البيانات المتعلقة بأسماء الطلاب الخريجين من المدرسة إلكترونياً.","تحديث المعلومات والبيانات المتعلقة بالمدرسة إلكترونياً.","طباعة بيانات تسجيل الطلاب المستجدين في المرحلة الابتدائية ورياض الأطفال ومعالجة أي خلل يطرأ أثناء التسجيل.","القيام باستخراج النتائج والإحصائيات والبيانات المتعلقة بالمدرسة إلكترونياً.","القيام بمتابعة كافة المتطلبات اللازمة لجهاز الحاسب الآلي والتنسيق مع المركز الوطني للمعلومات التربوية للاستفادة من الخدمات التي يقدمها.","تعبئة البيانات الخاصة ببرنامج التجهيزات المدرسية إلكترونياً.","القيام بأعمال المناوبة والإشراف اليومي على الطلاب قبل بداية الدوام الرسمي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.","القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته."]},{id:"guard",title:"حارس المدرسة",page:55,link:["يرتبط بوكيل الشؤون المدرسية."],goal:"الحفاظ على مبنى المدرسة وموجوداتها.",qualifications:["شهادة ابتدائية أو أعلى."],tasks:["يقوم بمباشرة عمله قبل حضور منسوبي المدرسة، وفتح وإغلاق باب المدرسة، وانصرافه مع آخر موظف، والتأكد من خلو المدرسة من الطلاب.","القيام بحراسة المبنى وما يحتويه.","عدم السماح لأي شخص بدخول المدرسة أو الخروج منها أثناء وبعد انتهاء الدوام إلا بإذن رسمي.","إبلاغ إدارة المدرسة والجهات المختصة عند حدوث أي طارئ وفق الآلية المعتمدة.","متابعة عمال النظافة والصيانة في أوقات الدراسة وخارجها أثناء القيام بعملهم.","التأكد من إغلاق الأبواب والنوافذ وإطفاء الأنوار والمكيفات والمراوح ومحابس المياه بعد انتهاء الدوام.","المحافظة على محتويات وممتلكات المدرسة.","القيام بفتح مبنى المدرسة خارج أوقات الدوام الرسمي بعد موافقة إدارة المدرسة.","السماح بدخول ومباشرة الفرق الإسعافية والحالات الطارئة أثناء الدوام الرسمي وفق التنظيمات المعتمدة.","المتابعة والتأكد من البطاقات الشخصية للمسؤولين عن نقل الطلاب بالسيارات الخاصة (خاص للطفولة المبكرة).","القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته."]},{id:"services-worker-f",title:"موظفة خدمات (مدارس رياض الأطفال)",page:56,link:["ترتبط بوكيلة المدرسة."],goal:"الاهتمام بمرافق المدرسة وتقديم الخدمات العامة.",qualifications:["الثانوية العامة."],tasks:["تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.","مرافقة أطفال ومنسوبات الروضة عند الحالات الطارئة.","مساعدة المعلمة في فصول رياض الأطفال في الجوانب غير التعليمية.","مساعدة المناوبات لمراقبة الأطفال قبل وأثناء وبعد الدوام.","عدم السماح لأي من الأطفال بالخروج من المدرسة أثناء الدوام الرسمي إلا بإذن خطي من الإدارة.","الاهتمام بمرافق المدرسة وتنظيمها أثناء الدوام المدرسي وفق النظام المتبع في المدرسة.","مرافقة الأطفال إلى دورات المياه والعناية بهم عند الحاجة.","تنظيم الفصول والملاعب الداخلية والخارجية آخر الدوام استعداداً لليوم التالي.","القيام بدورها المحدد في خطة الإخلاء المدرسي في الحالات الطارئة.","التأكد من خلو المدرسة من جميع (الأطفال) في نهاية الدوام المدرسي.","القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامها/مؤهلاتها."]},{id:"services-worker",title:"عامل خدمات",page:57,link:["يرتبط بوكيل الشؤون المدرسية."],goal:"الحفاظ على نظافة المدرسة وتقديم الخدمات العامة.",qualifications:["يجيد القراءة والكتابة."],tasks:["القيام بفتح وإقفال الأبواب الداخلية (داخل المدرسة) والنوافذ والأنوار والمكيفات والمراوح ومحابس المياه.","القيام بأعمال النظافة في الفصول وأفنية المدرسة وممراتها ومرافقها ودورات المياه.","تجهيز وتقديم أعمال الضيافة لإدارة المدرسة.","القيام بنقل المعاملات والأوراق داخل المدرسة، لتسهيل عمل كل من الهيئتين الإدارية والتعليمية.","التأكد من خلو المدرسة في نهاية وقت الدوام.","القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته."]}];
